Order acyclic(int nodes, const std::vector<Edge> &edges) {
    std::vector<bool> remaining(nodes, true);
    Order head, tail;
    for (int count = 0; count < nodes; ++count) {
        Order incoming(nodes), outgoing(nodes);
        for (const Edge &edge : edges)
            if (remaining[edge.from] && remaining[edge.to]) {
                ++outgoing[edge.from];
                ++incoming[edge.to];
            }
        int chosen = -1;
        bool toTail = false;
        for (int v = 0; v < nodes; ++v)
            if (remaining[v] && !outgoing[v]) {
                chosen = v;
                toTail = true;
                break;
            }
        if (chosen < 0)
            for (int v = 0; v < nodes; ++v)
                if (remaining[v] && !incoming[v]) {
                    chosen = v;
                    break;
                }
        if (chosen < 0)
            for (int v = 0; v < nodes; ++v)
                if (remaining[v] &&
                    (chosen < 0 || outgoing[v] - incoming[v] > outgoing[chosen] - incoming[chosen]))
                    chosen = v;
        remaining[chosen] = false;
        if (toTail)
            tail.insert(tail.begin(), chosen);
        else
            head.push_back(chosen);
    }
    head.insert(head.end(), tail.begin(), tail.end());
    return head;
}
LayeringResult assignLayers(const Orders &predecessors, const Orders &successors,
                            const Settings &settings) {
    int nodes = static_cast<int>(predecessors.size());
    LayeringResult out;
    out.height.resize(nodes);
    out.labels.resize(nodes);
    if (!settings.coffman) {
        std::vector<bool> known(nodes);
        std::function<int(int)> height = [&](int v) {
            if (known[v])
                return out.height[v];
            for (int next : successors[v])
                out.height[v] = std::max(out.height[v], height(next) + 1);
            known[v] = true;
            return out.height[v];
        };
        for (int v = 0; v < nodes; ++v)
            height(v);
    } else {
    }
    for (int v = 0; v < nodes; ++v)
        for (int next : successors[v])
            out.dummiesBefore += out.height[v] - out.height[next] - 1;
    return out;
}
Order positions(const Orders &orders, int count) {
    Order out(count);
    for (const Order &row : orders)
        for (std::size_t i = 0; i < row.size(); ++i)
            out[row[i]] = static_cast<int>(i);
    return out;
}
int gapCrossings(const std::vector<Segment> &segments, const Order &indices, const Order &pos,
                 int width) {
    std::vector<std::pair<int, int>> pairs;
    for (int index : indices) {
        const Segment &segment = segments[index];
        pairs.emplace_back(pos[segment.upper], pos[segment.lower]);
    }
    std::sort(pairs.begin(), pairs.end());
    int capacity = 1;
    while (capacity < width)
        capacity *= 2;
    Order tree(2 * capacity - 1);
    int out = 0;
    for (const auto &pair : pairs) {
        int at = pair.second + capacity - 1;
        ++tree[at];
        while (at) {
            if (at % 2)
                out += tree[at + 1];
            at = (at - 1) / 2;
            ++tree[at];
        }
    }
    return out;
}
int totalCrossings(const Layout &layout, const Orders &orders) {
    Order pos = positions(orders, static_cast<int>(layout.vertices.size()));
    int out = 0;
    for (std::size_t i = 0; i < layout.gaps.size(); ++i)
        out += gapCrossings(layout.segments, layout.gaps[i], pos,
                            static_cast<int>(orders[i + 1].size()));
    return out;
}
int bruteCrossings(Layout &layout, const Orders &orders, bool countEdges) {
    Order pos = positions(orders, static_cast<int>(layout.vertices.size()));
    int out = 0;
    for (const Order &indices : layout.gaps)
        for (std::size_t i = 0; i < indices.size(); ++i)
            for (std::size_t j = i + 1; j < indices.size(); ++j) {
                const Segment &a = layout.segments[indices[i]], &b = layout.segments[indices[j]];
                if ((pos[a.upper] - pos[b.upper]) * (pos[a.lower] - pos[b.lower]) < 0) {
                    ++out;
                    if (countEdges) {
                        ++layout.edges[a.edge].crossings;
                        ++layout.edges[b.edge].crossings;
                    }
                }
            }
    return out;
}
int adjacentCost(const Layout &layout, int left, int right, const Order &pos) {
    int out = 0;
    const Vertex &a = layout.vertices[left], &b = layout.vertices[right];
    for (int u : a.upper)
        for (int v : b.upper)
            if (pos[u] > pos[v])
                ++out;
    for (int u : a.lower)
        for (int v : b.lower)
            if (pos[u] > pos[v])
                ++out;
    return out;
}
