        layout.vertices[v].x = floorDiv(values[1] + values[2], 2);
        int low = layout.vertices[v].x - layout.vertices[v].left;
        if (!v || low < minimum)
            minimum = low;
    }
    for (Vertex &vertex : layout.vertices)
        vertex.x -= minimum;
