        ruler += static_cast<char>('0' + c % 10);
    Lines out{text("graph ", name, " ", columns, "x", rows), ruler};
    for (int r = 0; r < rows; ++r) {
        std::string number = std::to_string(r), line(3 - number.size(), ' ');
        line += number + " ";
        for (int c = 0; c < columns; ++c)
            line += character({r, c});
